parameters.jsCode:
const body = $json.body ?? $json;

const requiredFields = [
  'requester_name',
  'requester_email',
  'department',
  'title',
  'description',
  'declared_priority',
];

const missingFields = requiredFields.filter(
  field =>
    body[field] === undefined ||
    body[field] === null ||
    String(body[field]).trim() === ''
);

if (missingFields.length > 0) {
  throw new Error(
    `Missing required fields: ${missingFields.join(', ')}`
  );
}

const validPriorities = ['P1', 'P2', 'P3', 'P4'];

if (!validPriorities.includes(body.declared_priority)) {
  throw new Error(
    `Invalid priority: ${body.declared_priority}`
  );
}

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!emailRegex.test(body.requester_email)) {
  throw new Error('Invalid requester email');
}

return [
  {
    json: body
  }
];

const data = $json;

const normalizedTitle = data.title
  .trim()
  .toLowerCase()
  .replace(/\s+/g, ' ');

const normalizedEmail = data.requester_email
  .trim()
  .toLowerCase();

return [
  {
    json: {
      ...data,

      requester_email: normalizedEmail,

      normalized_title: normalizedTitle
    }
  }
];

const data = $('Normalize Request').item.json;

const createdAt = new Date();

function isWeekend(date) {
  const day = date.getUTCDay();
  return day === 0 || day === 6;
}

function addBusinessDays(date, numberOfDays) {
  const result = new Date(date);
  let remaining = numberOfDays;

  while (remaining > 0) {
    result.setUTCDate(result.getUTCDate() + 1);

    if (!isWeekend(result)) {
      remaining--;
    }
  }

  return result;
}

function setTo17UTC(date) {
  const result = new Date(date);
  result.setUTCHours(17, 0, 0, 0);
  return result;
}

let dueAt;

switch (data.declared_priority) {
  case 'P1':
    dueAt = new Date(
      createdAt.getTime() + 4 * 60 * 60 * 1000
    );
    break;

  case 'P2': {
    let dueDate = new Date(createdAt);

    if (
      isWeekend(dueDate) ||
      dueDate.getUTCHours() >= 17
    ) {
      dueDate = addBusinessDays(dueDate, 1);
    }

    dueAt = setTo17UTC(dueDate);
    break;
  }

  case 'P3': {
    let dueDate = addBusinessDays(createdAt, 3);
    dueAt = setTo17UTC(dueDate);
    break;
  }

  case 'P4': {
    let dueDate = addBusinessDays(createdAt, 5);
    dueAt = setTo17UTC(dueDate);
    break;
  }

  default:
    throw new Error(
      `Unsupported priority: ${data.declared_priority}`
    );
}

return [
  {
    json: {
      ...data,
      created_at: createdAt.toISOString(),
      due_at: dueAt.toISOString()
    }
  }
];

